-- chair-step: inverse of read_lane_v2_b3_46_interview_question — un-enrolls interview.question from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'interview' and table_name = 'question' and is_active);
select iam.apply_rls('interview', 'question', (select token from platform.entity_types where schema_name = 'interview' and table_name = 'question' and is_active), (select rls_variant from platform.entity_types where schema_name = 'interview' and table_name = 'question' and is_active));
